#' Classic DiD (2x2)
#'
#' Classic two-group, two-period difference-in-differences: group means, 
#' regression DiD and doubly robust, IPW and outcome-regression estimators.
#'
#' @examples
#' \donttest{
#' # d is a data frame with one row per unit and period
#' did22(data = d, dep = 'y', group = 'treated', period = 'year', id = 'id', covs = 'x')
#'}
#' @param data .
#' @param dep a string naming the outcome variable in \code{data}
#' @param group a string naming the 0/1 variable that marks the treated group
#' @param period a string naming a variable with exactly two values; the later
#'   (or last) value is the post period
#' @param id a string naming the unit identifier variable in \code{data}
#' @param covs a vector of strings naming covariates in \code{data}
#'   (optional); text and factor variables are dummy-coded
#' @param ols \code{TRUE} (default) or \code{FALSE}, regression
#'   difference-in-differences
#' @param dr \code{TRUE} (default) or \code{FALSE}, improved doubly robust
#'   estimator
#' @param drtrad \code{TRUE} or \code{FALSE} (default), traditional doubly
#'   robust estimator
#' @param ipw \code{TRUE} (default) or \code{FALSE}, inverse probability
#'   weighting estimator
#' @param or \code{TRUE} (default) or \code{FALSE}, outcome regression
#'   estimator
#' @param ciLevel the confidence level in percent (default 95)
#' @param plotPalette \code{'color'} (default, colour-blind safe) or
#'   \code{'gray'} (shades, shapes and line types for printing)
#' @param showHelp \code{TRUE} or \code{FALSE} (default), show notes on what
#'   the method does and how to read the results
#' @param showGuide \code{TRUE} or \code{FALSE} (default), show a guide to the
#'   variables and the data format
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$info} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$means} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$means$asDF}
#'
#' \code{as.data.frame(results$means)}
#'
#' @export
did22 <- function(
    data,
    dep,
    group,
    period,
    id = NULL,
    covs = NULL,
    ols = TRUE,
    dr = TRUE,
    drtrad = FALSE,
    ipw = TRUE,
    or = TRUE,
    ciLevel = 95,
    plotPalette = "color",
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("did22 requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(period)) period <- jmvcore::resolveQuo(jmvcore::enquo(period))
    if ( ! missing(id)) id <- jmvcore::resolveQuo(jmvcore::enquo(id))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(period), period, NULL),
            `if`( ! missing(id), id, NULL),
            `if`( ! missing(covs), covs, NULL))


    options <- did22Options$new(
        dep = dep,
        group = group,
        period = period,
        id = id,
        covs = covs,
        ols = ols,
        dr = dr,
        drtrad = drtrad,
        ipw = ipw,
        or = or,
        ciLevel = ciLevel,
        plotPalette = plotPalette,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- did22Class$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

